import React from "react";
import {AbsoluteFill, interpolate, useCurrentFrame, useVideoConfig} from "remotion";
type Props = {item: {id: string; props?: {headline?: string; accent?: string}}; headline?: string; accent?: string};
export default function Scene({item, headline = "MAKE IT MOVE", accent = "#E5FF00"}: Props) {
 const f = useCurrentFrame();
 const {width:w,height:h} = useVideoConfig();
 const title = item.props?.headline ?? headline, color = item.props?.accent ?? accent;
 const phase = (a:number,b:number) => interpolate(f,[a,b],[0,1],{extrapolateLeft:"clamp",extrapolateRight:"clamp",easing:t=>1-Math.pow(1-t,3)});
 const enter=phase(0,28), sweep=phase(48,78), settle=phase(108,130);
 const mask = `polygon(0 0,${sweep*125-25}% 0,${sweep*125-55}% 100%,0 100%)`;
 const typography:React.CSSProperties={position:"absolute",inset:0,display:"flex",flexDirection:"column",justifyContent:"center",padding:"8%",fontFamily:"Arial Black, Impact, sans-serif",fontWeight:900,fontSize:Math.min(w*.255,h*.23),lineHeight:.83,letterSpacing:"-.065em",overflowWrap:"anywhere",transform:`translateX(${(1-enter)*-w*.16}px) skewY(${-6*(1-settle)}deg) scale(${.88+.12*enter})`};
 const words=title.trim().split(/\s+/).map((word,i)=><div key={i}>{word}</div>);
 return <AbsoluteFill style={{background:"#1539F5",overflow:"hidden"}}>
  <div style={{position:"absolute",inset:0,background:color,clipPath:mask}}/>
  <div style={{position:"absolute",left:"8%",right:"8%",top:"8%",height:3,background:color,transform:`scaleX(${enter})`,transformOrigin:"left"}}/>
  <div data-ck-layer={item.id} data-ck-path="headline" data-ck-element="headline" style={{position:"absolute",inset:0,clipPath:`inset(${(1-enter)*49}% 0)`}}>
   <div style={{...typography,color}}>{words}</div>
   <div aria-hidden style={{position:"absolute",inset:0,clipPath:mask}}><div style={{...typography,color:"#1539F5"}}>{words}</div></div>
  </div>
  <div data-ck-layer={item.id} data-ck-path="accent" data-ck-element="accent-rule" style={{position:"absolute",bottom:"8%",left:"8%",width:w*.84,height:12,background:"#1539F5",borderBottom:`4px solid ${color}`,transform:`scaleX(${enter})`,transformOrigin:"left"}}/>
  <div style={{position:"absolute",top:"10%",right:"8%",fontFamily:"monospace",fontSize:Math.max(12,w*.018),fontWeight:700,color:sweep>.8?"#1539F5":color}}>MOTION / 001</div>
 </AbsoluteFill>;
}
